// CSD_RATIONALE_BEGIN
// This strategy solves math word problems step by step, ensuring each arithmetic computation is enclosed in << >> delimiters.
// It transitions between unconstrained and constrained phases based on the presence of "<<". In the constrained phase,
// it uses ConfidenceGatedStep to ensure grammar validity while allowing free sampling when the model's top choice is invalid.
// This approach balances exploration and exploitation to find valid solutions efficiently.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var inWindow: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant inWindow ==> parser.IsValidPrefix(currentConstrained)
  invariant inWindow ==> forall t: Token :: t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  decreases maxSteps - steps, if inWindow then 1 else 0
{
  if !inWindow {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      inWindow := true;
      currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    if parser.IsCompletePrefix(currentConstrained) {
      inWindow := false;
    } else {
      var next, wasConstrained := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);
      generated := generated + [next];
      steps := steps + 1;
      if wasConstrained {
        currentConstrained := currentConstrained + [next];
        if Contains(next, ">>") { inWindow := false; }
      } else {
        inWindow := false;
      }
    }
  }
}
cost := helpers.cost;

